from __future__ import absolute_import
import time
from selenium.webdriver.common.by import By
from taf.selenium.sc.pages.view import ViewPanel
from taf.selenium.sc.pages.navigatable_page import NavigatablePage
from taf.selenium.sc.pages.configuration_management.configuration_menu import ConfigurationMenu


class SaveScfFilePage(NavigatablePage):
    _TARGET_TAB_XPATH = '//*[@id="commissioning-header"]//span[contains(text(), "Save configuration")]'
    _MENU_ROUTE_LIST = ["commissioning", "Save", _TARGET_TAB_XPATH]

    def __init__(self, driver, download_checker):
        super(SaveScfFilePage, self).__init__(driver, ConfigurationMenu)
        self._save_scf_panel = SaveScfFilePanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def save_scf_file(self, download_timeout=1800):
        return self._save_scf_panel.save_scf_file(download_timeout)


class SaveScfFilePanel(ViewPanel):
    _DOWNLOAD_SCF_BUTTON = '//*[@id="backup-prepared-step"]//button[text()="Download"]'

    def __init__(self, driver, download_checker):
        super(SaveScfFilePanel, self).__init__(driver, download_checker)

    def save_scf_file(self, download_timeout=1800):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._DOWNLOAD_SCF_BUTTON))
        return self.download_files(start_time, download_timeout)
